String[] lines = input.split("\\r?\\n");
for (String line : lines) {
    line = line.trim();
    if (line.contains(" ")) {
        String[] nums = line.split("\\s+");
        int sum = 0;
        for (String n : nums) {
            if (!n.isEmpty()) {
                sum += Integer.parseInt(n);
            }
        }
        return String.valueOf(sum);
    }
}
return "0";
